// 1. The Generic Interface Contract
interface IRepository<T> {
  findById(id: string): Promise<T>;
  save(item: T): Promise<void>;
}

interface User { id: string; name: string; }

// 2. The Concrete Implementation (e.g., using MongoDB)
class MongoUserRepository implements IRepository<User> {
  async findById(id: string) {
    console.log(`Executing Mongo query for ${id}...`);
    return { id, name: "Alice" };
  }

  async save(user: User) {
    console.log(`Saving ${user.name} to MongoDB...`);
  }
}

// 3. Business Logic (Completely blind to MongoDB!)
class UserService {
  // It only asks for the Interface contract
  constructor(private repo: IRepository<User>) {}

  async upgradeUser(id: string) {
    const user = await this.repo.findById(id);
    // business logic here...
    await this.repo.save(user);
  }
}
